    getDaysBetweenDates(start, end, dayName) {
      debugger;
      var result = [];
      var days = {
        sun: 0,
        mon: 1,
        tue: 2,
        wed: 3,
        thu: 4,
        fri: 5,
        sat: 6
      };
      var day = days[dayName.toLowerCase().substr(0, 3)]; // Copy start date

      var current = new Date(start);
      var current1 = new Date(start.setHours(0, 0, 0, 0));
      var enddate1 = new Date(end.setHours(0, 0, 0, 0)); // Shift to next of required days

      current.setDate(current.getDate() + (day - current.getDay() + 7) % 7);
      current1.setDate(current1.getDate() + (day - current1.getDay() + 7) % 7); // While less than end date, add dates to result array
      // var startdate=this.getDateItem(current);
      // var endate1=this.getDateItem(end);

      while (current1 <= enddate1) {
        result.push(new Date(+current));
        current.setDate(current.getDate() + 7);
        current1.setDate(current1.getDate() + 7);
      }

      console.log(result);
      return result;
    }

